<?php
declare(strict_types=1);require __DIR__.'/core.php';begin_session();$error='';$notice='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){handle_action(valid_text($_POST['action']??'',40));header('Location: index.php?tab='.urlencode(valid_text($_POST['tab']??'menu',30)).'&saved=1',true,303);exit;}}catch(Throwable $e){$error=$e->getMessage();http_response_code(in_array($e->getCode(),[400,401,403,409,429,503],true)?$e->getCode():400);}
try{$state=tx(fn($s)=>$s,false);$user=current_user($state);}catch(Throwable $e){$state=null;$user=null;$error=$e->getMessage();}
$tab=in_array($_GET['tab']??'',['menu','products','users','password','history'],true)?$_GET['tab']:'menu';if($user&&$user['must_change'])$tab='password';
$groups=['wochenkarte'=>'Wochenkarte','klassiker'=>'Unsere Klassiker','weisswein'=>'Weißwein','rotwein'=>'Rotwein'];
function hidden_fields(string $action,string $tab):void{global $state;echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="tab" value="'.h($tab).'"><input type="hidden" name="revision" value="'.h($state['revision']??0).'">';}
function euro(int $n):string{return number_format($n/100,2,',','');}
function field(string $label,string $name,string $value='',string $type='text',bool $required=true):void{echo '<label class="field">'.h($label).'<input type="'.h($type).'" name="'.h($name).'" value="'.h($value).'"'.($required?' required':'').' '.($type==='password'?'autocomplete="new-password"':'').' maxlength="2000"></label>';}
