 <form method="post" class="logout"><?php hidden_fields('logout','menu');?><button class="btn outline">Abmelden</button></form><p class="draft-state">Angemeldet als <strong><?=h($user['name'])?></strong> · <?=h($user['role'])?> · Stand <?=h($state['revision'])?></p>
