 <h2>Produkte</h2><p><a class="btn outline" href="?tab=products">+ Neues Produkt</a></p><table><thead><tr><th>Produkt</th><th>Preis</th><th>Status</th></tr></thead><tbody><?php foreach($state['catalog']['products']as$item):?><tr><td><a href="?tab=products&amp;edit=<?=urlencode($item['id'])?>"><?=h($item['name'])?></a></td><td><?=h(euro($item['price']))?> €</td><td><?=($item['active']??true)?'Sichtbar':'Versteckt'?></td></tr><?php endforeach;?></tbody></table><section class="account"><h3><?=$selected?'Produkt bearbeiten':'Neues Produkt'?></h3><form method="post"><?php hidden_fields('save_product','products');?><div class="manage-grid"><?php field('Artikel-ID / Seitenadresse','product_id',$p['id']);field('Name','name',$p['name']);field('Marke / Region','brand',$p['brand']);field('Format, z. B. 0,75 l oder 110 g','pack',$p['pack']);?><label class="field">Kategorie<select name="category"><?php foreach(['conservas'=>'Konserven','embutidos'=>'Wurst & Cecina','weisswein'=>'Weißwein','rotwein'=>'Rotwein']as$k=>$v):?><option value="<?=h($k)?>" <?=$p['category']===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><label class="field">Mengeneinheit<select name="unit"><option value="g" <?=$p['unit']==='g'?'selected':''?>>Gramm</option><option value="ml" <?=$p['unit']==='ml'?'selected':''?>>Milliliter</option></select></label><?php field('Inhalt in g / ml','amount',(string)$p['amount'],'number');field('Einzelpreis €','price',euro($p['price']));field('Flaschen / Einheiten pro Karton · 0 = kein Karton','case',(string)$p['case'],'number');field('Kartonpreis €','casePrice',euro($p['casePrice']));field('Bestand in einzelnen Einheiten','stock',(string)($p['stock']??0),'number');field('Jahrgang · optional','year',$p['year']??'','text',false);?></div><label class="field">Beschreibung<textarea name="description" maxlength="2000"><?=h($p['description'])?></textarea></label><label class="field">Zutaten, Allergene, Lagerung und Hinweise<textarea name="note" maxlength="5000"><?=h($p['note']??'')?></textarea></label><?php field('HTTPS-Referenz · optional','source',$p['source']??'','url',false);?><p><label><input type="checkbox" name="pickup" <?=$p['pickup']?'checked':''?>> Nur Abholung</label></p><p><label><input type="checkbox" name="active" <?=($p['active']??true)?'checked':''?>> Im Shop anzeigen</label></p><button class="btn">Produktentwurf speichern</button></form></section>
 <?php elseif($tab==='users'&&$user['role']==='admin'):?>
 <h2>Team & Zugänge</h2><p class="note">Jedes Konto hat ein eigenes Passwort. Ein neues Startpasswort wird nie im Klartext gespeichert. Eine Änderung sperrt alte Sitzungen.</p><?php $accounts=array_values($state['users']);$accounts[]=['id'=>'','name'=>'','role'=>'editor','active'=>true];foreach($accounts as$a):?><section class="account"><h3><?=h($a['name']?:'Neues Teammitglied')?></h3><form method="post"><?php hidden_fields('user_save','users');?><input type="hidden" name="user_id" value="<?=h($a['id'])?>"><div class="manage-grid"><?php field('Benutzername','user_name',$a['name']);field($a['id']?'Neues Startpasswort · leer = unverändert':'Startpasswort · mindestens 12 Zeichen','initial_password','','password',!$a['id']);?><label class="field">Berechtigung<select name="role"><option value="editor" <?=$a['role']==='editor'?'selected':''?>>Redaktion · Inhalte bearbeiten</option><option value="admin" <?=$a['role']==='admin'?'selected':''?>>Administrator · veröffentlichen & Team</option></select></label><label class="field"><input type="checkbox" name="active" <?=$a['active']?'checked':''?>> Zugang aktiv</label></div><button class="btn">Konto speichern</button></form></section><?php endforeach;?>
 <?php elseif($tab==='history'):?>
